#!/bin/sh
# LX2-d round 2: run every source-attribution check the fragment cites. Usage: sh sources_checks_r2.sh <src_dir> <checkout>
# <src_dir> is populated by fetch_sources_r2.sh (plain curl). Writes its output to stdout.
set -e
SRC=${1:-/tmp/lx2d-r2-src}; CO=${2:-.}
S="$CO/ledgers/LX2/scripts/LX2-d-r2"
echo "== statute 1933 (COMPS-1884): sections 5(a), 5(c), 6(a), 6(c), 8(a), 8(b) and 8(d) trigger"
python3 -I "$S/norm_grep.py" "$SRC/COMPS-1884.txt" "Unless a registration statement is in effect as to a security" "unless a registration statement has been filed as to such security" "Any security may be registered" "shall be deemed to have taken place upon the receipt thereof" "Except as hereinafter provided, the effective date of a registration statement shall be the twentieth day" "If it appears to the Commission that a registration statement is on its face incomplete or inaccurate in any material respect" "refusing to permit such statement to become effective until it has been amended in accordance with such order" "If it appears to the Commission at any time that the registration statement includes any untrue statement of a material fact" "issue a stop order suspending the effectiveness" "the stop order shall cease to be effective" | cut -c1-160
echo "== statute 1934 (COMPS-1885): sections 12(a), 12(b), 12(d), 13(a), 15(d)(1) and the asset-backed carve-out"
python3 -I "$S/norm_grep.py" "$SRC/COMPS-1885.txt" "to effect any transaction in any security" "by the issuer filing an application with the exchange" "shall become effective thirty days after the receipt of such certification" "may be withdrawn or stricken from listing and registration in accordance with the rules of the exchange" "Every issuer of a security registered pursuant to section 12 of this title shall file" "which has become effective pursuant to the Securities Act of 1933" "other than any class of asset-backed securities, to which the registration statement relates are held of record by less than 300 persons" | cut -c1-160
echo "== opinions: U.S. Reports printed pages"
python3 -I "$S/opinion_pages.py" "$SRC/USREPORTS-463-646.txt" "any manipulative or deceptive device or contrivance" "does not arise from the mere possession of nonpublic market information" "Absent some personal gain, there has been no breach of duty to stockholders" "a direct or indirect personal benefit from the disclosure, such as a pecuniary gain or a reputational benefit" "Determining whether an insider personally benefits from a particular disclosure, a question of fact" "an independent element of a Rule 10b-5 violation" "Thus, a tippee assumes a fiduciary duty" "The elements of fiduciary duty and exploitation of nonpublic information also exist when an insider makes a gift"
python3 -I "$S/opinion_pages.py" "$SRC/USREPORTS-521-642.txt" "classical theory applies not only to officers, directors, and other permanent insiders" "a securities transaction, and thereby violates" "if the fiduciary discloses to the source that he plans to trade" "the trader may still be liable under the misappropriation theory" "uses the information to purchase or sell securities" "The theory does not catch all conceivable forms of fraud"
echo "== SR 26-2 letter and attachment (PDF pages via form feed)"
python3 -I "$S/norm_grep.py" "$SRC/letter.txt" "supersedes and replaces SR letter 11-7" "over \$30 billion in total assets regulated by the Federal Reserve" | cut -c1-160
python3 -I "$S/norm_grep.py" "$SRC/att.txt" "simple arithmetic calculations, such as those found within spreadsheets" "The term “model risk” refers to the potential for adverse financial consequences" "does not set forth enforceable standards or prescriptive requirements" "supervisory action may result for any violations of law" | cut -c1-160
python3 -I "$S/pdf_pages_r2.py" "$SRC/att.txt" "responsible for adopting model" "Outcomes analysis compares model outputs" "does not set forth enforceable standards" "supervisory action may result for any violations of law" "Outcomes Analysis"
echo "== CFA Standards pages (III(A), VI(A)): HTML text"
python3 -I "$S/norm_grep.py" "$SRC/cfa-standards-of-practice-iii-a.html.txt" "Fiduciary duties are often imposed by law or regulation" "does not render all members and candidates fiduciaries" "neither impose such a legal responsibility" | cut -c1-160
python3 -I "$S/norm_grep.py" "$SRC/cfa-standards-of-practice-vi-a.html.txt" "Best practice is to avoid the conflict by asking his employer" | cut -c1-160
echo "== words hit and bias in attachment and letter (expect none)"
grep -c -i -E "\bhit\b|\bbias\b" "$SRC/att.txt" "$SRC/letter.txt" || true
